# Homebrew formula for g4.
#
# GENERATED by rules_brew -- do not edit by hand;
# the next release overwrites this file.
class G4 < Formula
  desc "Linear-trunk version control: FUSE mount plus git collaboration commands"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/g4-0.1.7/g4-darwin-universal.tar.xz",
    linux: on_arch_conditional(
      arm:   "https://github.com/qzmfranklin/homebrew-tap/releases/download/g4-0.1.7/g4-linux-arm64.tar.xz",
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/g4-0.1.7/g4-linux-amd64.tar.xz",
    ),
  )
  version "0.1.7"
  sha256 on_system_conditional(
    macos: "9e9599d3c99929af6e80304a1168ef4e46bb7e714a57c15d80cc458e464ea9e9",
    linux: on_arch_conditional(
      arm:   "12f9eea970b311f9cfcbf29d7e6e1a2dc8f6fc98cdafe819d09961d22f0e1daa",
      intel: "170144e312e7beeae59e5d712e256b614eff2b54638737842717f81f3bce5a92",
    ),
  )
  license :cannot_represent

  def install
    bin.install "g4"

    # The ONE git-g4 link (plan 0003 row 2.34): git's external-command
    # mechanism runs `git-g4` from PATH when `git g4` matches no builtin or
    # alias, and the g4 binary dispatches on argv[0] — a `git-g4` basename runs
    # the arguments through the `g4 git` group — so `git g4 land` (and siblings)
    # work in any repository with zero per-repo configuration. The per-verb
    # `git-<cmd>` links are RETIRED: on PATH they would BEAT a repository's own
    # `git land` aliases (git's external-over-alias precedence), shadowing them
    # wherever g4 is installed. The ad-hoc codesign below signs the one Mach-O
    # the link points at, so the symlink needs no signing of its own.
    bin.install_symlink bin/"g4" => "git-g4"

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"g4"
      system "/usr/bin/xattr", "-cr", bin/"g4"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"g4"
    end

    # `--print SHELL` writes the script to STDOUT and installs nothing; a
    # bare `g4 complete` would edit the user's rc file, which a
    # formula must not do.
    #
    # generate_completions_from_executable appends the shell name as the
    # final argument and writes each script where brew expects it, so it
    # replaces one hand-rolled safe_popen_read per shell.
    generate_completions_from_executable(
      bin/"g4",
      "complete",
      "--print",
      shells: [:bash, :zsh],
    )
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/g4"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew g4 at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed g4 is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"g4") unless linked.symlink?
  end


  def caveats
    <<~EOS
      g4 ships two working surfaces at this version:

        g4 mount    the FUSE virtual filesystem (g4 umount tears it down)
        git g4      the collaboration group: land, sync, fold, mend, view, web

      Every other subcommand (sync, diff, land, pick, revert, log, undo, br, stat,
      bisect, serve) is a stub at this version.

      The git group is entered through GIT, not through g4's own command list:
      this formula links git-g4 to the g4 binary, and git's external-command
      mechanism runs it when you type `git g4 …` — so `git g4 land`, `git g4 sync`,
      `git g4 fold`, `git g4 mend`, `git g4 view` and `git g4 web` work in any
      repository with zero per-repo configuration. The group is deliberately
      absent from `g4 --help` and the completions — `git g4` is the only surface.
      The plain `git land` form is deliberately NOT installed: a `git-<cmd>`
      external on PATH beats a repository's own `git land` aliases, so g4 never
      places one.

      Homebrew installs shell completions for bash and zsh, but it deliberately
      never edits your rc files — <TAB> completion stays inert until your shell
      is wired to load them.

      zsh: the script lands in $(brew --prefix)/share/zsh/site-functions, which
      `brew shellenv` adds to FPATH. Ensure `eval "$(brew shellenv)"` runs before
      completion initialises (with oh-my-zsh, before the line that sources it —
      oh-my-zsh calls compinit itself), and add to ~/.zshrc unless your setup
      already runs compinit:

        autoload -Uz compinit
        compinit

      zsh caches the completion list in ~/.zcompdump; if one already exists
      from before this install, refresh it once: `rm -f ~/.zcompdump`.

      bash: install one of the bash-completion formulae and source the loader
      from ~/.bash_profile:

        brew install bash-completion      # for the macOS system bash (3.2)
        brew install bash-completion@2    # instead, for Homebrew bash 4+
        [ -r "$(brew --prefix)/etc/profile.d/bash_completion.sh" ] && \
          . "$(brew --prefix)/etc/profile.d/bash_completion.sh"

      `g4 <TAB>` completes g4's own subcommands; `git g4 <TAB>` is not completed
      — git's own completion does not know external commands.

      The binary does not link libfuse: the mount paths load libfuse.2.dylib with
      dlopen at execution time, so every command — `g4 git` included — runs on a
      machine with no macFUSE installed. The formula deliberately declares no
      depends_on (proper macFUSE use requires a reboot — far too heavy for a
      git-only user); only the disk-flavor `g4 mount` needs the library, and when
      libfuse is absent it refuses at runtime with the remedy:

        brew install --cask macfuse

      The bypass flavor, `g4 mount --flavor=bypass`, is a passthrough mount that
      needs no macFUSE at all.

      The published binary is ad-hoc signed, not notarized. Homebrew strips the
      quarantine attribute on install, so it runs when installed through brew; a
      binary downloaded directly from the release page may additionally need
      `xattr -cr <path>` before macOS will exec it.
    EOS
  end

  test do
    # --help smokes only: the TUI (`git g4 view`) and the web server
    # (`git g4 web`) are interactive and are not formula-tested. Assert on the
    # usage lines, which survive argument changes, rather than on about text.
    # The git-g4 leg is the ONLY surface smoke (plan 0003 row 2.34): the group
    # is entered through the symlink (the argv[0] dispatch rewrites the
    # invocation to `g4 git land …`), and the `g4 git` registration itself is
    # HIDDEN from `g4 --help` — the direct spelling is deliberately untested
    # and untaught.
    assert_match(/Usage: g4 git land/, shell_output("#{bin}/git-g4 land --help"))
    assert_match(/Usage: g4 git sync/, shell_output("#{bin}/git-g4 sync --help"))
  end
end
